=== FILE: tb/tb_irq_ctrl.sv ===
// Self-checking testbench for irq_ctrl (task prj-486b52a6aa:testbench).
// Requirement: Verify the existing interrupt controller RTL with a SystemVerilog testbench.
// Expected values come from interface_spec.md (tags [req:IRQ-*] below), either
// as hand-computed constants or from a reference model written from the spec text.
// Inputs are driven at the falling edge; outputs are sampled after the rising edge.
// Only the top module tb_irq_ctrl calls $finish and prints the single verdict line.
`timescale 1ns / 1ps

module tb_irq_ctrl;
    wire [31:0] pass_n8, fail_n8, pass_n2, fail_n2, pass_n32, fail_n32;
    wire        done_n8, done_n2, done_n32;

    // [req:IRQ-PARAM] the default and both ends of the legal range of N.
    irq_ctrl_test #(.N(8))  u_n8  (.passed(pass_n8),  .failed(fail_n8),  .done(done_n8));
    irq_ctrl_test #(.N(2))  u_n2  (.passed(pass_n2),  .failed(fail_n2),  .done(done_n2));
    irq_ctrl_test #(.N(32)) u_n32 (.passed(pass_n32), .failed(fail_n32), .done(done_n32));

    string  nonce;
    bit     have_nonce;
    bit     reported;
    integer total_pass;
    integer total_fail;

    task automatic report(input integer extra_fail);
        total_pass = pass_n8 + pass_n2 + pass_n32;
        total_fail = fail_n8 + fail_n2 + fail_n32 + extra_fail + (have_nonce ? 0 : 1);
        $display("NIRMAAN-SIM %s %0d passed, %0d failed", nonce, total_pass, total_fail);
    endtask

    initial begin
        reported   = 1'b0;
        have_nonce = 1'b0;
        nonce      = "MISSING";
        if      ($value$plusargs("NIRMAAN_NONCE=%s", nonce))     have_nonce = 1'b1;
        else if ($value$plusargs("nirmaan_nonce=%s", nonce))     have_nonce = 1'b1;
        else if ($value$plusargs("NIRMAAN_SIM_NONCE=%s", nonce)) have_nonce = 1'b1;
        else if ($value$plusargs("nirmaan_sim_nonce=%s", nonce)) have_nonce = 1'b1;
        else if ($value$plusargs("nonce=%s", nonce))             have_nonce = 1'b1;
        else if ($value$plusargs("NONCE=%s", nonce))             have_nonce = 1'b1;
        if (!have_nonce) begin
            nonce = "MISSING";
            $display("ERROR: no nonce plusarg found; the verdict counts one failure");
        end
        wait (done_n8 === 1'b1 && done_n2 === 1'b1 && done_n32 === 1'b1);
        #1;
        if (!reported) begin
            reported = 1'b1;
            report(0);
            $finish;
        end
    end

    // Watchdog: a hung test reports a failure instead of never finishing.
    initial begin
        #5_000_000;
        if (!reported) begin
            reported = 1'b1;
            $display("ERROR: watchdog expired before all tests finished");
            report(1);
            $finish;
        end
    end
endmodule

module irq_ctrl_test #(
    parameter integer N = 8
) (
    output logic [31:0] passed,
    output logic [31:0] failed,
    output logic        done
);
    localparam logic [31:0] MASK = (N >= 32) ? 32'hFFFF_FFFF : ((32'd1 << N) - 32'd1);
    localparam logic [31:0] ALL  = 32'hFFFF_FFFF;
    localparam logic [1:0]  A_EN = 2'd0, A_MODE = 2'd1, A_PEND = 2'd2, A_CLAIM = 2'd3;
    localparam integer B0 = 0;      // first source, highest priority
    localparam integer B1 = 1;
    localparam integer BM = N / 2;  // a middle source
    localparam integer BT = N - 1;  // last source, lowest priority

    logic        clk = 1'b0;
    logic        rst_n;
    logic [31:0] src_v;
    logic        we;
    logic [1:0]  addr;
    logic [31:0] wdata;
    wire  [31:0] rdata;
    wire         irq;
    wire  [4:0]  irq_id;

    irq_ctrl #(.N(N)) dut (
        .clk(clk), .rst_n(rst_n), .src(src_v[N-1:0]), .we(we), .addr(addr),
        .wdata(wdata), .rdata(rdata), .irq(irq), .irq_id(irq_id)
    );

    always #50 clk = ~clk;

    // ---------------- Reference model, written from interface_spec.md ----------------
    logic [31:0] m_en, m_mode, m_pend, m_srcq;

    always @(posedge clk) begin : spec_model
        integer      k;
        logic [31:0] np;
        logic        det;
        logic        clr;
        if (!rst_n) begin
            // [req:IRQ-RESET]
            m_en   = 32'd0;
            m_mode = 32'd0;
            m_pend = 32'd0;
            m_srcq = 32'd0;
        end else begin
            np = m_pend;
            for (k = 0; k < N; k = k + 1) begin
                // [req:IRQ-LEVEL] [req:IRQ-EDGE] [req:IRQ-DETECT-DISABLED]
                det = m_mode[k] ? (src_v[k] && !m_srcq[k]) : src_v[k];
                // [req:IRQ-W1C] [req:IRQ-ACK]; a number of N or more matches no k
                clr = we && ((addr == A_PEND && wdata[k]) || (addr == A_CLAIM && wdata[4:0] == k));
                // [req:IRQ-SET-WINS]
                if (det)      np[k] = 1'b1;
                else if (clr) np[k] = 1'b0;
            end
            // [req:IRQ-REG-RW] [req:IRQ-PARAM]
            if (we && addr == A_EN)   m_en   = wdata & MASK;
            if (we && addr == A_MODE) m_mode = wdata & MASK;
            m_pend = np;
            m_srcq = src_v & MASK;
        end
    end

    // ---------------- Helpers ----------------
    function automatic logic [31:0] bitv(input integer k);
        bitv = 32'd1 << k;
    endfunction

    task automatic check32(input logic [31:0] got, input logic [31:0] exp,
                           input string where, input string what);
        if (got === exp) passed = passed + 32'd1;
        else begin
            failed = failed + 32'd1;
            $display("FAIL N=%0d t=%0t %s: %s: got 0x%08h, expected 0x%08h",
                     N, $time, where, what, got, exp);
        end
    endtask

    // Compare every output with the model. rdata is read at all four addresses
    // with no clock edge in between [req:IRQ-READ].
    task automatic check_all(input string where);
        logic [31:0] act;
        logic [31:0] claim;
        logic        e_irq;
        logic [4:0]  e_id;
        logic        found;
        logic [1:0]  keep;
        integer      k;
        act   = m_pend & m_en;
        e_irq = (act != 32'd0);                        // [req:IRQ-MASK]
        e_id  = 5'd0;
        found = 1'b0;
        for (k = 0; k < N; k = k + 1)                  // [req:IRQ-PRIORITY]
            if (!found && act[k]) begin
                e_id  = k[4:0];
                found = 1'b1;
            end
        claim = {e_irq, 26'd0, e_id};                  // [req:IRQ-CLAIM]
        check32({31'd0, irq},    {31'd0, e_irq}, where, "model irq");
        check32({27'd0, irq_id}, {27'd0, e_id},  where, "model irq_id");
        keep = addr;
        addr = A_EN;    #1; check32(rdata, m_en,   where, "model ENABLE");
        addr = A_MODE;  #1; check32(rdata, m_mode, where, "model MODE");
        addr = A_PEND;  #1; check32(rdata, m_pend, where, "model PENDING");
        addr = A_CLAIM; #1; check32(rdata, claim,  where, "model CLAIM");
        addr = keep;
    endtask

    // One rising edge: drive at the falling edge, sample after the rising edge.
    task automatic tick(input logic r, input logic [31:0] s, input logic w,
                        input logic [1:0] a, input logic [31:0] d, input string where);
        @(negedge clk);
        rst_n = r;
        src_v = s;
        we    = w;
        addr  = a;
        wdata = d;
        @(posedge clk);
        #1;
        we = 1'b0;
        check_all(where);
    endtask

    // Directed checks against a value worked out by hand from the spec.
    task automatic expect_reg(input logic [1:0] a, input logic [31:0] exp, input string where);
        logic [1:0] keep;
        keep = addr;
        addr = a;
        #1;
        check32(rdata, exp, where, "directed register read");
        addr = keep;
    endtask

    task automatic expect_irq(input logic e_irq, input logic [4:0] e_id, input string where);
        logic [1:0] keep;
        check32({31'd0, irq},    {31'd0, e_irq}, where, "directed irq");
        check32({27'd0, irq_id}, {27'd0, e_id},  where, "directed irq_id");
        keep = addr;
        addr = A_CLAIM;
        #1;
        check32(rdata, {e_irq, 26'd0, e_id}, where, "directed CLAIM read");
        addr = keep;
    endtask

    // ---------------- Scenarios ----------------
    integer      n;
    logic [31:0] rv, sv, dv;
    logic [1:0]  ra;
    logic        rw, rr;

    initial begin
        passed = 32'd0;
        failed = 32'd0;
        done   = 1'b0;
        rst_n  = 1'b0;
        src_v  = 32'd0;
        we     = 1'b0;
        addr   = 2'd0;
        wdata  = 32'd0;

        // S1 reset [req:IRQ-RESET]
        tick(0, 0, 0, A_EN, 0, "S1 reset edge 1");
        tick(0, 0, 0, A_EN, 0, "S1 reset edge 2");
        expect_reg(A_EN,   32'd0, "S1 ENABLE is 0 after reset");
        expect_reg(A_MODE, 32'd0, "S1 MODE is 0 after reset");
        expect_reg(A_PEND, 32'd0, "S1 PENDING is 0 after reset");
        expect_irq(0, 0, "S1 no interrupt after reset");

        // S2 register read/write [req:IRQ-REG-RW] [req:IRQ-PARAM] [req:IRQ-W1C]
        tick(1, 0, 1, A_EN, 32'hA5A5_A5A5, "S2 write ENABLE pattern");
        expect_reg(A_EN,   32'hA5A5_A5A5 & MASK, "S2 ENABLE holds pattern, upper bits zero");
        expect_reg(A_MODE, 32'd0, "S2 MODE unchanged by ENABLE write");
        tick(1, 0, 1, A_MODE, 32'h5A5A_5A5A, "S2 write MODE pattern");
        expect_reg(A_MODE, 32'h5A5A_5A5A & MASK, "S2 MODE holds pattern, upper bits zero");
        expect_reg(A_EN,   32'hA5A5_A5A5 & MASK, "S2 ENABLE unchanged by MODE write");
        tick(1, 0, 1, A_EN, ALL, "S2 write ENABLE all ones");
        expect_reg(A_EN, MASK, "S2 ENABLE bits N and up read zero");
        tick(1, 0, 1, A_MODE, ALL, "S2 write MODE all ones");
        expect_reg(A_MODE, MASK, "S2 MODE bits N and up read zero");
        tick(1, 0, 1, A_PEND, ALL, "S2 write PENDING all ones");
        expect_reg(A_PEND, 32'd0, "S2 a PENDING write never sets a bit");
        tick(1, 0, 1, A_CLAIM, 0, "S2 write CLAIM");
        expect_reg(A_EN,   MASK, "S2 ENABLE unchanged by CLAIM write");
        expect_reg(A_MODE, MASK, "S2 MODE unchanged by CLAIM write");
        tick(1, 0, 1, A_EN, 32'd0, "S2 clear ENABLE");
        tick(1, 0, 0, A_EN, ALL, "S2 we low: no write");
        expect_reg(A_EN, 32'd0, "S2 ENABLE not written while we low");
        tick(1, 0, 1, A_MODE, 32'd0, "S2 clear MODE");
        expect_reg(A_MODE, 32'd0, "S2 MODE cleared");

        // S3 level detection on a disabled source, then masking
        // [req:IRQ-LEVEL] [req:IRQ-DETECT-DISABLED] [req:IRQ-MASK] [req:IRQ-CLAIM]
        tick(1, bitv(BM), 0, A_EN, 0, "S3 level pulse on disabled source");
        expect_reg(A_PEND, bitv(BM), "S3 disabled source still sets PENDING");
        expect_irq(0, 0, "S3 disabled pending source raises no irq");
        tick(1, 0, 0, A_EN, 0, "S3 input falls");
        expect_reg(A_PEND, bitv(BM), "S3 PENDING stays set after input falls");
        tick(1, 0, 1, A_EN, bitv(BM), "S3 enable the pending source");
        expect_irq(1, BM, "S3 enabling a pending source raises irq");
        tick(1, 0, 1, A_PEND, 32'd0, "S3 PENDING write of zeros");
        expect_reg(A_PEND, bitv(BM), "S3 writing 0 leaves PENDING unchanged");
        tick(1, 0, 0, A_PEND, ALL, "S3 PENDING address with we low");
        expect_reg(A_PEND, bitv(BM), "S3 no clear while we low");
        expect_irq(1, BM, "S3 irq still high");
        tick(1, 0, 1, A_PEND, bitv(BM), "S3 W1C the source");
        expect_reg(A_PEND, 32'd0, "S3 W1C clears the bit");
        expect_irq(0, 0, "S3 irq low after clear");
        tick(1, 0, 1, A_EN, 32'd0, "S3 clear ENABLE");

        // S4 selective write-one-to-clear [req:IRQ-W1C]
        tick(1, bitv(B0) | bitv(BT), 0, A_EN, 0, "S4 pulse first and last source");
        expect_reg(A_PEND, bitv(B0) | bitv(BT), "S4 both detected");
        tick(1, 0, 1, A_PEND, bitv(BT), "S4 W1C last source");
        expect_reg(A_PEND, bitv(B0), "S4 only the written bit clears");
        tick(1, 0, 1, A_PEND, ~bitv(B0), "S4 W1C every bit but bit 0");
        expect_reg(A_PEND, bitv(B0), "S4 bit written 0 unchanged");
        tick(1, 0, 1, A_PEND, ALL, "S4 W1C all");
        expect_reg(A_PEND, 32'd0, "S4 all cleared");

        // S5 rising-edge detection [req:IRQ-EDGE] [req:IRQ-SET-WINS]
        tick(1, 0, 1, A_MODE, bitv(B1), "S5 make source 1 edge triggered");
        expect_reg(A_MODE, bitv(B1), "S5 MODE written");
        tick(1, bitv(B1), 0, A_EN, 0, "S5 rise");
        expect_reg(A_PEND, bitv(B1), "S5 rising edge sets PENDING");
        tick(1, bitv(B1), 1, A_PEND, bitv(B1), "S5 clear while held high");
        expect_reg(A_PEND, 32'd0, "S5 held-high edge source not re-detected");
        tick(1, bitv(B1), 0, A_EN, 0, "S5 held high 1");
        tick(1, bitv(B1), 0, A_EN, 0, "S5 held high 2");
        expect_reg(A_PEND, 32'd0, "S5 an input held high sets PENDING once");
        tick(1, 0, 0, A_EN, 0, "S5 fall");
        expect_reg(A_PEND, 32'd0, "S5 a fall detects nothing");
        tick(1, bitv(B1), 0, A_EN, 0, "S5 second rise");
        expect_reg(A_PEND, bitv(B1), "S5 a new rise sets PENDING again");
        tick(1, 0, 1, A_PEND, ALL, "S5 clear, input falls");
        expect_reg(A_PEND, 32'd0, "S5 cleared");
        tick(1, bitv(B0) | bitv(B1), 0, A_EN, 0, "S5 level 0 and edge 1 rise together");
        expect_reg(A_PEND, bitv(B0) | bitv(B1), "S5 two sources detected at one edge");
        tick(1, bitv(B0) | bitv(B1), 1, A_PEND, ALL, "S5 clear both while held high");
        expect_reg(A_PEND, bitv(B0), "S5 level source re-sets, edge source does not");
        tick(1, 0, 1, A_PEND, ALL, "S5 clear, inputs fall");
        expect_reg(A_PEND, 32'd0, "S5 cleared again");
        tick(1, 0, 1, A_MODE, 32'd0, "S5 MODE back to level");

        // S6 a detection wins over a clear at the same edge [req:IRQ-SET-WINS] [req:IRQ-ACK]
        tick(1, bitv(BT), 0, A_EN, 0, "S6 level source high");
        expect_reg(A_PEND, bitv(BT), "S6 detected");
        tick(1, bitv(BT), 1, A_PEND, bitv(BT), "S6 W1C while input high");
        expect_reg(A_PEND, bitv(BT), "S6 level source cleared while high stays pending");
        tick(1, bitv(BT), 1, A_CLAIM, BT, "S6 acknowledge while input high");
        expect_reg(A_PEND, bitv(BT), "S6 level source acknowledged while high stays pending");
        tick(1, 0, 1, A_CLAIM, BT, "S6 acknowledge after input falls");
        expect_reg(A_PEND, 32'd0, "S6 acknowledge clears once the input is low");
        tick(1, 0, 1, A_MODE, bitv(B1), "S6 make source 1 edge triggered");
        tick(1, bitv(B1), 1, A_PEND, bitv(B1), "S6 rise at the same edge as W1C");
        expect_reg(A_PEND, bitv(B1), "S6 edge detected at a clearing edge stays pending");
        tick(1, bitv(B1), 1, A_CLAIM, B1, "S6 acknowledge while held, no new edge");
        expect_reg(A_PEND, 32'd0, "S6 acknowledge clears the edge source");
        tick(1, 0, 0, A_EN, 0, "S6 fall");
        tick(1, bitv(B1), 1, A_CLAIM, B1, "S6 rise at the same edge as acknowledge");
        expect_reg(A_PEND, bitv(B1), "S6 edge detected at an acknowledging edge stays pending");
        tick(1, 0, 1, A_PEND, ALL, "S6 clear");
        tick(1, 0, 1, A_MODE, 32'd0, "S6 MODE back to level");
        expect_reg(A_PEND, 32'd0, "S6 cleared");

        // S7 acknowledge through CLAIM [req:IRQ-ACK] [req:IRQ-READ]
        tick(1, MASK, 0, A_EN, 0, "S7 pulse every source");
        expect_reg(A_PEND, MASK, "S7 every source pending");
        tick(1, 0, 1, A_CLAIM, BM, "S7 acknowledge the middle source");
        expect_reg(A_PEND, MASK & ~bitv(BM), "S7 only the acknowledged bit clears");
        if (N < 32) begin
            tick(1, 0, 1, A_CLAIM, N, "S7 acknowledge number N");
            expect_reg(A_PEND, MASK & ~bitv(BM), "S7 a number of N changes nothing");
            tick(1, 0, 1, A_CLAIM, 31, "S7 acknowledge number 31");
            expect_reg(A_PEND, MASK & ~bitv(BM), "S7 a number above N changes nothing");
        end
        tick(1, 0, 1, A_CLAIM, 32'hFFFF_FFE0, "S7 acknowledge 0 with upper wdata bits set");
        expect_reg(A_PEND, MASK & ~bitv(BM) & ~bitv(B0), "S7 only wdata bits 4 to 0 name the source");
        tick(1, 0, 1, A_CLAIM, 32'hFFFF_FFE0 | BT, "S7 acknowledge last source with upper bits set");
        expect_reg(A_PEND, MASK & ~bitv(BM) & ~bitv(B0) & ~bitv(BT), "S7 last source acknowledged");
        tick(1, 0, 0, A_CLAIM, B1, "S7 read CLAIM with we low");
        expect_reg(A_PEND, MASK & ~bitv(BM) & ~bitv(B0) & ~bitv(BT), "S7 reading CLAIM acknowledges nothing");
        tick(1, 0, 1, A_PEND, ALL, "S7 clear");
        expect_reg(A_PEND, 32'd0, "S7 cleared");

        // S8 priority with several requesters [req:IRQ-PRIORITY] [req:IRQ-MASK] [req:IRQ-CLAIM]
        tick(1, MASK, 0, A_EN, 0, "S8 pulse every source");
        expect_irq(0, 0, "S8 nothing enabled: irq low, id 0");
        tick(1, 0, 1, A_EN, MASK, "S8 enable all");
        expect_irq(1, B0, "S8 source 0 wins");
        tick(1, 0, 1, A_EN, MASK & ~bitv(B0), "S8 mask source 0");
        expect_irq(1, B1, "S8 source 1 wins once 0 is masked");
        tick(1, 0, 1, A_EN, bitv(BT) | bitv(BM), "S8 enable middle and last");
        expect_irq(1, BM, "S8 lower number wins");
        tick(1, 0, 1, A_EN, bitv(BT), "S8 enable last only");
        expect_irq(1, BT, "S8 last source alone");
        tick(1, 0, 1, A_EN, 32'd0, "S8 enable none");
        expect_irq(0, 0, "S8 all masked: irq low, id 0");
        expect_reg(A_PEND, MASK, "S8 masking keeps PENDING");
        tick(1, 0, 1, A_EN, MASK, "S8 enable all again");
        expect_irq(1, 0, "S8 source 0 wins again");
        tick(1, 0, 1, A_CLAIM, 0, "S8 acknowledge 0");
        expect_irq(1, 1, "S8 next priority after acknowledge");
        tick(1, 0, 1, A_CLAIM, 1, "S8 acknowledge 1");
        if (N > 2) expect_irq(1, 2, "S8 source 2 next");
        else       expect_irq(0, 0, "S8 nothing left for N=2");
        tick(1, MASK, 0, A_EN, 0, "S8 re-pulse every source");
        tick(1, 0, 1, A_PEND, MASK & ~bitv(BT), "S8 clear all but last");
        expect_reg(A_PEND, bitv(BT), "S8 only last pending");
        expect_irq(1, BT, "S8 claim names the last source");
        tick(1, 0, 1, A_CLAIM, BT, "S8 acknowledge last");
        expect_irq(0, 0, "S8 irq low, id 0");
        tick(1, 0, 1, A_EN, 32'd0, "S8 clear ENABLE");

        // S9 latency: irq follows the registers with no extra edge [req:IRQ-LATENCY]
        tick(1, 0, 1, A_EN, bitv(BT), "S9 enable last source");
        expect_irq(0, 0, "S9 irq low before detection");
        @(negedge clk);
        src_v = bitv(BT);
        addr  = A_PEND;
        #10;
        check32({31'd0, irq}, 32'd0, "S9 input high before the edge", "irq waits for the edge");
        check32(rdata, 32'd0, "S9 input high before the edge", "PENDING waits for the edge");
        @(posedge clk);
        #1;
        check32({31'd0, irq}, 32'd1, "S9 right after the detecting edge", "irq high");
        check32({27'd0, irq_id}, BT, "S9 right after the detecting edge", "irq_id");
        check_all("S9 detecting edge");
        tick(1, 0, 1, A_PEND, bitv(BT), "S9 clear");
        expect_irq(0, 0, "S9 irq low right after the clearing edge");
        tick(1, 0, 1, A_EN, 32'd0, "S9 clear ENABLE");

        // S11 reset in the middle of operation [req:IRQ-RESET]
        tick(1, 0, 1, A_EN, MASK, "S11 enable all");
        tick(1, 0, 1, A_MODE, bitv(B1), "S11 source 1 edge triggered");
        tick(1, MASK, 0, A_EN, 0, "S11 every source high");
        expect_reg(A_PEND, MASK, "S11 all pending");
        expect_irq(1, 0, "S11 irq high");
        tick(0, MASK, 1, A_EN, MASK, "S11 reset with inputs high and a write presented");
        expect_reg(A_EN,   32'd0, "S11 reset clears ENABLE over a write");
        expect_reg(A_MODE, 32'd0, "S11 reset clears MODE");
        expect_reg(A_PEND, 32'd0, "S11 reset clears PENDING over detection");
        expect_irq(0, 0, "S11 irq low in reset");
        tick(1, MASK, 0, A_EN, 0, "S11 first edge after reset, inputs high");
        expect_reg(A_PEND, MASK, "S11 level detection resumes after reset");
        expect_irq(0, 0, "S11 nothing enabled after reset");
        tick(1, 0, 1, A_PEND, ALL, "S11 clear");

        // S12 random stimulus, every cycle compared with the reference model
        for (n = 0; n < 600; n = n + 1) begin
            rv = $random;
            sv = $random;
            sv = sv & $random & MASK;
            dv = $random;
            rr = (rv[5:0] != 6'd0);
            rw = rv[6] | rv[7];
            ra = rv[9:8];
            if (ra == A_CLAIM && rv[10]) dv = {27'd0, rv[15:11]};
            tick(rr, sv, rw, ra, dv, "S12 random");
        end

        done = 1'b1;
    end
